const ws = new WebSocket("wss://api.quak.party/v1/play/talk/live");
ws.binaryType = "arraybuffer";
ws.onopen = () =>
  ws.send(JSON.stringify({ type: "start", ticket, to: ["Kitchen"], format: { encoding: "opus", sampleRate: 48000 } }));
ws.onmessage = (event) => {
  const message = JSON.parse(event.data);
  if (message.type === "ready") startSendingOpusPackets(ws); // ws.send(packet), one 20 ms packet each
  if (message.type === "done") console.log("credits", message.credits, "balance", message.balance);
  if (message.type === "error") console.error(message.code, message.message);
};
// later: ws.send(JSON.stringify({ type: "end" }))

const ws = new WebSocket("wss://api.quak.party/v1/plays/watch");
ws.onopen = () => ws.send(JSON.stringify({ type: "auth", ticket }));
ws.onmessage = (event) => {
  const message = JSON.parse(event.data);
  if (message.type === "play") console.log(message.data.id, message.data.status);
};
